import type {
  ComponentContext,
  ComponentFile,
  ComponentTemplate,
} from '@teambit/generator';

// TODO: replace this with "import {ComponentTemplateOptions} from '@teambit/generator';" once v1.3 is released
export type RspackReactAppTemplateOptions = Partial<
  Pick<ComponentTemplate, 'name' | 'description' | 'hidden' | 'env'>
>;

/**
 * Generates a React app component bound to the rspack app type
 * (`@teambit/rspack.app-types.react-rspack`) — the same app type used by
 * `teambit.rspack/envs/react-env` and `teambit.cloud/envs/cloud-react`.
 */
export class RspackReactAppTemplate implements ComponentTemplate {
  constructor(
    readonly name = 'react-app',
    readonly description = 'a template for generating react rspack app components',
    readonly hidden = false,
    readonly env?: string
  ) {}

  generateFiles(context: ComponentContext): ComponentFile[] {
    const { name, namePascalCase: Name } = context;
    return [
      {
        relativePath: 'index.ts',
        content: `export { ${Name} } from "./${name}";\n`,
      },
      {
        relativePath: `${name}.tsx`,
        content: `export function ${Name}() {
  return <h1>Hello World!</h1>;
}`,
      },
      {
        relativePath: `${name}.composition.tsx`,
        content: `import { ${Name} } from "./${name}";

export const ${Name}Basic = () => <${Name} />`,
      },
      {
        relativePath: 'client.app-root.tsx',
        content: `import { createRoot } from 'react-dom/client';
import { ${Name} } from "./${name}";

const container = document.getElementById('root');
const root = createRoot(container!);
root.render(<${Name} />);
`,
      },
      {
        relativePath: 'server.app-root.tsx',
        content: `import { renderToString } from 'react-dom/server';
import { ${Name} } from "./${name}";

type RenderOptions = {
  path: string;
};

export function render({ path }: RenderOptions) {
  return renderToString(<${Name} />);
}
`,
      },
      {
        relativePath: `${name}.bit-app.ts`,
        content: `import { RspackReactApp } from '@teambit/rspack.app-types.react-rspack';

export default RspackReactApp.from({
  name: '${name}',
});
`,
      },
    ];
  }

  static from(options: RspackReactAppTemplateOptions = {}) {
    return () =>
      new RspackReactAppTemplate(
        options.name,
        options.description,
        options.hidden,
        options.env
      );
  }
}
